mapper.select:
SELECT r.id, r.return_id AS returnId, r.return_code AS returnCode, r.from_node_id AS fromNodeId, fn.node_name AS fromNodeName, r.to_node_id AS toNodeId, tn.node_name AS toNodeName, r.return_status AS returnStatus, r.return_type AS returnType, r.apply_user_id AS applyUserId, r.apply_time AS applyTime, r.audit_user_id AS auditUserId, r.audit_time AS auditTime, r.audit_opinion AS auditOpinion, r.remark, r.create_time AS createTime FROM spd_dept_return r LEFT JOIN spd_org_node fn ON r.from_node_id = fn.node_id AND fn.del_flag = 0 LEFT JOIN spd_org_node tn ON r.to_node_id = tn.node_id AND tn.del_flag = 0 WHERE r.del_flag = 0
AND r.return_status = #{form.returnStatus}
AND r.return_type = #{form.returnType}
AND r.return_code LIKE CONCAT('%', #{form.returnCode}, '%')
ORDER BY r.create_time DESC
